/**
 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
 *
 * Must call (do not reimplement): emit, shouldFilterArchived
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { shouldFilterArchived } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one pass sweeps. */
const ORG_BATCH = 50;

/** Archived issues are never overdue — an archived issue has no due date. */
const LIVE_ONLY = {} as const;

const logger = createLogger("overdue-issue-job");

/**
 * Issues already announced this process's lifetime. A later sweep still
 * finds a still-open, still-overdue issue — this is what keeps the job from
 * re-emitting `issue.overdue` for it on every pass.
 */
const reported = new Set<string>();

/** Test-only: clears the reported set so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  reported.clear();
}

/**
 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
 * no notification logic: it announces the fact, and whoever cares (in-app
 * alerts, the digest, webhooks) reacts on the bus.
 */
export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
  return runJob("overdue-issues", async (result) => {
    if (!shouldFilterArchived(LIVE_ONLY)) {
      logger.warn("archive scope misconfigured; skipping sweep", {});
      return;
    }

    const stamp = toIsoTimestamp(now);
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

      for (const issue of overdue) {
        if (issue.dueAt === null) continue;
        if (reported.has(issue.id)) continue;

        try {
          await emit("issue.overdue", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            issueId: issue.id,
            projectId: issue.projectId,
            dueAt: issue.dueAt,
            assigneeId: issue.assigneeId,
          });
          reported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}
/**
 * Interval-based scheduler started from `src/instrumentation.ts`; decides which job kind is due.
 */
import { createLogger } from "@/lib/logger";
import { drain, enqueue, pendingCount } from "./queue";
import { toIsoTimestamp } from "@/types/common";
import type { JobKind } from "./queue";

/** How often `tick()` runs once the scheduler is started. */
const TICK_INTERVAL_MS = 60_000;

/** Minimum gap between two runs of the same job kind, in minutes. */
const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
  "digest-email": 60,
  "overdue-issues": 60,
  "webhook-delivery": 1,
  "usage-rollup": 15,
  "search-reindex": 1_440,
  "cleanup-archived": 1_440,
  "trial-expiry": 360,
};

const logger = createLogger("job-scheduler");

let timer: ReturnType<typeof setInterval> | null = null;
const lastRunAt = new Map<JobKind, number>();

/**
 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
 * keeps a process alive — a scheduler that blocks shutdown is worse than one
 * that misses the last tick.
 */
export function startScheduler(): void {
  if (timer !== null) return;

  timer = setInterval(() => {
    void tick(new Date()).catch((error: unknown) => {
      logger.error("scheduler tick failed", {
        reason: error instanceof Error ? error.message : String(error),
      });
    });
  }, TICK_INTERVAL_MS);

  timer.unref?.();
  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
}

export function stopScheduler(): void {
  if (timer === null) return;
  clearInterval(timer);
  timer = null;
  lastRunAt.clear();
}

export function isSchedulerRunning(): boolean {
  return timer !== null;
}

/**
 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
 * out from the interval so tests can drive it with an explicit clock instead
 * of waiting a minute.
 */
export async function tick(now: Date): Promise<void> {
  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
    if (!isDue(kind, now)) continue;

    lastRunAt.set(kind, now.getTime());
    enqueue({
      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
      kind,
      runAt: toIsoTimestamp(now),
      attempts: 0,
      payload: {},
    });
  }

  const completed = await drain();
  if (completed > 0 || pendingCount() > 0) {
    logger.debug("tick complete", { completed, pending: pendingCount() });
  }
}

function isDue(kind: JobKind, now: Date): boolean {
  const previous = lastRunAt.get(kind);
  if (previous === undefined) return true;
  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
}
/**
 * Cron-style trigger for the overdue scan.
 *
 * Owner D. The job emits `issue.overdue`; the notification fan-out is a
 * subscriber, so this route never sends anything itself.
 *
 * Must call (do not reimplement): runOverdueIssueJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runOverdueIssueJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Project rows: cursor listing, slug/key uniqueness, soft delete and restore.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived, uniqueSlug
 */
import { and, count, desc, eq, isNotNull, like, lt, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, projects } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";

export async function findProjectById(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  return row ? toProject(row) : null;
}

export async function findProjectBySlug(
  orgId: OrgId,
  slug: string,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.slug, slug)))
    .get();
  return row ? toProject(row) : null;
}

export async function listProjects(
  input: ListProjectsInput,
): Promise<Page<Project>> {
  const db = getDb();
  const sort = { sortColumn: projects.createdAt, idColumn: projects.id };

  // The rows and the total must agree on the archive scope, so normalise the
  // filter's loose `includeArchived` into one `ArchiveScope` up front.
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  const filters = compact(
    orgPredicate(projects.orgId, input.orgId),
    livePredicate(projects.archivedAt, scope),
    input.status === undefined ? undefined : eq(projects.status, input.status),
    input.query === undefined
      ? undefined
      : like(projects.name, `%${input.query}%`),
  );

  const total = db
    .select({ value: count() })
    .from(projects)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(projects)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(projects.createdAt), desc(projects.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(rows, input.limit, total?.value ?? 0, toProject, (row) => ({
    id: row.id,
    sortValue: row.createdAt,
  }));
}

/** Counts live projects by default; the `projects` quota reads this. */
export async function countProjects(
  orgId: OrgId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(projects)
    .where(
      and(
        ...compact(
          orgPredicate(projects.orgId, orgId),
          livePredicate(projects.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertProject(
  input: CreateProjectInput,
): Promise<Project> {
  const taken = await listTakenProjectSlugs(input.orgId);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(projects)
    .values({
      id: newId(),
      orgId: input.orgId,
      name: input.name,
      slug,
      key: input.key,
      description: input.description,
      visibility: input.visibility,
      status: "active",
      leadId: input.leadId,
      color: input.color,
      startsAt: null,
      targetDate: input.targetDate,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toProject(row);
}

export async function updateProject(
  input: UpdateProjectInput,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.visibility === undefined
        ? {}
        : { visibility: input.visibility }),
      ...(input.status === undefined ? {} : { status: input.status }),
      ...(input.leadId === undefined ? {} : { leadId: input.leadId }),
      ...(input.color === undefined ? {} : { color: input.color }),
      ...(input.targetDate === undefined
        ? {}
        : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(projects.orgId, input.orgId),
        eq(projects.id, input.projectId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Project ${input.projectId} not found`);
  return toProject(row);
}

export async function archiveProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(archivePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

export async function restoreProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(restorePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

/** Includes archived slugs — a restored project must not collide. */
export async function listTakenProjectSlugs(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: projects.slug })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.slug);
}

/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ProjectStats> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.projectId, projectId),
    ...compact(livePredicate(issues.archivedAt, {})),
  );

  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, eq(issues.status, "done")))
    .get();

  const all = db.select({ value: count() }).from(issues).where(scope).get();

  const overdue = db
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        scope,
        isNotNull(issues.dueAt),
        lt(issues.dueAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();

  const lastActivity = db
    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
    .from(issues)
    .where(scope)
    .get();

  const closedCount = closed?.value ?? 0;

  return {
    projectId,
    openIssues: (all?.value ?? 0) - closedCount,
    closedIssues: closedCount,
    overdueIssues: overdue?.value ?? 0,
    lastActivityAt:
      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
  };
}
import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
  "none",
  "low",
  "medium",
  "high",
  "urgent",
];

export interface Issue extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

export interface IssueLabel extends TenantScoped {
  readonly id: LabelId;
  readonly name: string;
  readonly color: string;
  readonly description: string | null;
}

export interface IssueAttachment extends Timestamps, TenantScoped {
  readonly id: AttachmentId;
  readonly issueId: IssueId;
  readonly filename: string;
  readonly contentType: string;
  readonly sizeBytes: number;
  readonly uploadedBy: UserId;
}

/** Filter accepted by the issue repository, service layer and list UI alike. */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatus[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: UserId | null;
  readonly authorId?: UserId;
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  readonly dueBefore?: IsoTimestamp;
  readonly includeArchived?: boolean;
}

export interface IssueWithRelations {
  readonly issue: Issue;
  readonly labels: readonly IssueLabel[];
  readonly commentCount: number;
  readonly attachmentCount: number;
}

/** One column of the kanban board; the board is an ordered list of these. */
export interface IssueBoardColumn {
  readonly status: IssueStatus;
  readonly issues: readonly Issue[];
  readonly total: number;
}
import type {
  IsoTimestamp,
  NotificationId,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type NotificationKind =
  | "issue_assigned"
  | "issue_status_changed"
  | "issue_due_soon"
  | "issue_overdue"
  | "comment_created"
  | "comment_mention"
  | "member_invited"
  | "member_joined"
  | "project_archived"
  | "plan_limit_reached"
  | "digest_ready";

export type NotificationChannel = "in_app" | "email" | "webhook";

export interface Notification extends Timestamps, TenantScoped {
  readonly id: NotificationId;
  readonly recipientId: UserId;
  readonly kind: NotificationKind;
  readonly title: string;
  readonly body: string;
  readonly href: string;
  readonly actorId: UserId | null;
  readonly readAt: IsoTimestamp | null;
  readonly channels: readonly NotificationChannel[];
}

/** Per-user delivery matrix; the fan-out consults this before every send. */
export interface NotificationPreference extends TenantScoped {
  readonly userId: UserId;
  readonly kind: NotificationKind;
  readonly inApp: boolean;
  readonly email: boolean;
  readonly digestOnly: boolean;
}

/** One item queued for the daily digest email. */
export interface DigestEntry {
  readonly notificationId: NotificationId;
  readonly kind: NotificationKind;
  readonly title: string;
  readonly href: string;
  readonly occurredAt: IsoTimestamp;
}

export interface DigestBundle extends TenantScoped {
  readonly recipientId: UserId;
  readonly entries: readonly DigestEntry[];
  readonly windowStart: IsoTimestamp;
  readonly windowEnd: IsoTimestamp;
}

